    marks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                marks[r-c] = v
    offsets = sorted(marks)
    # Select the smallest period consistent with all observed bands.
    period = max(1, len(set(marks.values())))
    for p in range(1, max(2, h+w+1)):
        residues = {}
        ok = True
        for d, color in marks.items():
            k = d % p
            if k in residues and residues[k] != color:
                ok = False
                break
            residues[k] = color
        if ok and len(residues) == len(set(marks.values())):
            period = p
